// Data access + helpers. The scenario snapshot (public/mock_bundle.json, regenerated by
// backend/export_mock.py) is compiled into the app so the dashboard renders instantly with
// no loading screen; the FastAPI engine is only probed in the background for the status badge.
import SNAPSHOT from '../../public/mock_bundle.json'

const API = import.meta.env.VITE_API_URL ?? ''

export const BUNDLE = SNAPSHOT

export async function probeApi() {
  try {
    const ctrl = new AbortController()
    const t = setTimeout(() => ctrl.abort(), 2500)
    const r = await fetch(`${API}/api/health`, { signal: ctrl.signal })
    clearTimeout(t)
    return r.ok ? 'api' : 'offline'
  } catch {
    return 'offline'
  }
}

// Sector-tailored SMS / WhatsApp text sent to a zone's stakeholders
export function alertMessage(zone) {
  const lbl = zone.eta_high_hours != null ? horizonLabel(zone.eta_high_hours) : null
  const when = lbl ? `Seuil critique prévu ${lbl.day} à ${lbl.time}.` : 'Surveillance renforcée.'
  return `⚠ BlueVision · ${zone.short} — risque d’algues toxiques ${LEVEL[zone.level].label.toLowerCase()}. ${when} Action : ${zone.actions[0]}.`
}

export async function sendAlert(zoneId, hour, source) {
  if (source === 'api') {
    try {
      const r = await fetch(`${API}/api/alerts/${zoneId}?hour=${Math.round(hour)}`, { method: 'POST' })
      if (r.ok) return r.json()
    } catch { /* fall through to simulation */ }
  }
  await new Promise((res) => setTimeout(res, 600))
  return { sent: true, simulated: true }
}

// ---- interpolation between 3-hourly frames ---------------------------------
export function frameIndex(bundle, hour) {
  const hours = bundle.grid.hours
  const step = hours[1] - hours[0]
  const f = Math.min(Math.max(hour / step, 0), hours.length - 1)
  const i = Math.min(Math.floor(f), hours.length - 2)
  return { i, w: f - i }
}

export function interpFrame(bundle, hour) {
  const { i, w } = frameIndex(bundle, hour)
  const a = bundle.frames[i]
  const b = bundle.frames[i + 1]
  const lerp = (x, y) => x + (y - x) * w
  const zones = a.zones.map((za, k) => {
    const zb = b.zones[k]
    const score = lerp(za.score, zb.score)
    const level = score >= 65 ? 'high' : score >= 35 ? 'moderate' : 'low'
    const actions = (w < 0.5 ? za : zb).actions
    return { ...za, score, level, actions: level === za.level ? za.actions : level === zb.level ? zb.actions : actions }
  })
  const cond = {}
  for (const k of Object.keys(a.conditions)) {
    const va = a.conditions[k], vb = b.conditions[k]
    cond[k] = typeof va === 'number' ? lerp(va, vb) : va
  }
  return {
    hour,
    confidence: lerp(a.confidence, b.confidence),
    conditions: cond,
    zones,
    global_index: Math.max(...zones.map((z) => z.score)),
  }
}

export function interpGrid(bundle, hour) {
  const { i, w } = frameIndex(bundle, hour)
  const A = bundle.grid.frames[i]
  const B = bundle.grid.frames[i + 1]
  const out = new Float32Array(A.length)
  for (let k = 0; k < A.length; k++) out[k] = A[k] + (B[k] - A[k]) * w
  return out
}

// ---- colors ------------------------------------------------------------------
export const LEVEL = {
  low: { label: 'Faible', color: '#059669', bg: 'bg-emerald-400/15', text: 'text-emerald-300' },
  moderate: { label: 'Modéré', color: '#d97706', bg: 'bg-amber-400/15', text: 'text-amber-300' },
  high: { label: 'Élevé', color: '#e11d48', bg: 'bg-rose-500/15', text: 'text-rose-300' },
}

// risk 0..100 -> [r,g,b,a]   green -> yellow -> orange -> red -> magenta
const STOPS = [
  [0, [16, 185, 129, 0]],
  [8, [16, 185, 129, 0]],
  [20, [52, 211, 153, 90]],
  [35, [250, 204, 21, 150]],
  [50, [251, 146, 60, 185]],
  [65, [244, 63, 94, 210]],
  [85, [225, 29, 72, 230]],
  [100, [192, 38, 211, 240]],
]
export const RAMP = (() => {
  const lut = new Uint8ClampedArray(101 * 4)
  for (let v = 0; v <= 100; v++) {
    let j = 0
    while (j < STOPS.length - 2 && v > STOPS[j + 1][0]) j++
    const [v0, c0] = STOPS[j], [v1, c1] = STOPS[j + 1]
    const t = (v - v0) / (v1 - v0 || 1)
    for (let c = 0; c < 4; c++) lut[v * 4 + c] = c0[c] + (c1[c] - c0[c]) * t
  }
  return lut
})()

export function levelColor(score) {
  return score >= 65 ? LEVEL.high.color : score >= 35 ? LEVEL.moderate.color : LEVEL.low.color
}

// ---- time labels ---------------------------------------------------------------
export function issueDate() {
  const d = new Date()
  d.setHours(6, 0, 0, 0)
  return d
}
const fmt = new Intl.DateTimeFormat('fr-FR', { weekday: 'short', day: 'numeric', month: 'short' })
const fmtH = new Intl.DateTimeFormat('fr-FR', { hour: '2-digit', minute: '2-digit' })
export function horizonLabel(hour) {
  const d = new Date(issueDate().getTime() + hour * 3600e3)
  return { day: fmt.format(d), time: fmtH.format(d) }
}

// ---- geometry --------------------------------------------------------------------
export function pointInRing(lon, lat, ring) {
  let inside = false
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [xi, yi] = ring[i], [xj, yj] = ring[j]
    if ((yi > lat) !== (yj > lat) && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside
  }
  return inside
}
